/* Pre-render bridge for /studio/.
 *
 * studio/index.html is generated by tools/build-studio.mjs from
 * studio/src/index.html. The served file carries the fully rendered markup in
 * <div id="dc-prerender"> so that crawlers, link previews and visitors without
 * JavaScript get the real case studies, ladder and comparison rather than
 * {{ activeStep.price }}. The Design Canvas template lives in
 * assets/dc-template.js instead of in the HTML.
 *
 * dc-runtime.js boots by finding an <x-dc> element and replacing it with
 * #dc-root, so this script — which runs during parsing, before the deferred
 * runtime — puts that element back from the template and takes the static
 * fallback out. Both happen synchronously, so nothing is ever on screen twice.
 *
 * With JavaScript off, neither runs and the static markup simply stays.
 */
(function () {
  'use strict';
  var slot = document.getElementById('dc-prerender');
  if (!slot) return;

  var tpl = window.__dcTemplate;
  if (typeof tpl !== 'string') return; // template missing: keep the static page

  var dc = document.createElement('x-dc');
  dc.innerHTML = tpl;
  slot.parentNode.replaceChild(dc, slot);
})();
